+++ b/src/items.js
@@ -1,5 +1,7 @@
 import { fetchItems, saveItem } from "./store.js";

+let lastId = 0;
+
 /** Items that carry `tag`. */
 export async function findByTag(tag) {
   const items = await fetchItems();
@@ -8,8 +10,33 @@ export async function findByTag(tag) {

 /** Adds an item with the next free id. */
 export async function addItem(item) {
-  if (!item.name) throw new Error("Item needs a name.");
+  if (!item || typeof item !== "object" || Array.isArray(item))
+    throw new Error("Item must be an object.");
+  if (typeof item.name !== "string" || !item.name.trim())
+    throw new Error("Item needs a name.");
+  if (!Number.isInteger(item.qty) || item.qty < 0)
+    throw new Error("Item quantity must be a whole number, 0 or more.");
+  const tags = item.tags === undefined ? [] : item.tags;
+  if (!Array.isArray(tags) || tags.some((tag) => typeof tag !== "string"))
+    throw new Error("Item tags must be an array of strings.");
+  const unit = item.unit === undefined ? "" : item.unit;
+  if (typeof unit !== "string" || (unit !== "" && !/^[a-z]+$/i.test(unit)))
+    throw new Error("Item unit must be a word or an empty string.");
+  if (item.expires !== undefined) {
+    if (typeof item.expires !== "string" || !/^\d{4}-\d{2}-\d{2}$/.test(item.expires))
+      throw new Error("Item expiry must be a calendar date in YYYY-MM-DD format.");
+    const date = new Date(`${item.expires}T00:00:00.000Z`);
+    if (!Number.isFinite(date.getTime()) || date.toISOString().slice(0, 10) !== item.expires)
+      throw new Error("Item expiry must be a valid calendar date.");
+  }
   const items = await fetchItems();
-  const id = Math.max(0, ...items.map((i) => i.id)) + 1;
-  return saveItem({ tags: [], unit: "", ...item, id });
+  const id = Math.max(lastId, ...items.map((i) => i.id)) + 1;
+  lastId = id;
+  return saveItem({
+    ...item,
+    id,
+    name: item.name.trim().toLowerCase(),
+    tags: [...new Set(tags.map((tag) => tag.toLowerCase()))].sort(),
+    unit,
+  });
 }
